'use client'

import type { LucideIcon } from 'lucide-react'
import { cn } from '@/lib/utils'

interface KpiCardProps {
  label: string
  value: string | number
  subtext: string
  icon: LucideIcon
  trend?: 'up' | 'down' | 'neutral'
  /** When true, lower value is better (e.g., no-show rate). Inverts trend color logic. */
  invertTrend?: boolean
  loading?: boolean
  index?: number
  /** CSS color value for the accent top stripe. Defaults to primary purple. */
  accentColor?: string
}

function getTrendColor(trend: 'up' | 'down' | 'neutral', invertTrend: boolean): string {
  if (trend === 'neutral') return 'text-muted-foreground'
  const isPositive = invertTrend ? trend === 'down' : trend === 'up'
  return isPositive ? 'text-emerald-500' : 'text-destructive'
}

export function KpiCard({
  label,
  value,
  subtext,
  icon: Icon,
  trend = 'neutral',
  invertTrend = false,
  index = 0,
  accentColor = 'oklch(62% 0.24 292 / 0.6)',
}: KpiCardProps) {
  return (
    <div
      className={cn(
        'group relative overflow-hidden rounded-xl border border-border/40',
        'bg-[var(--color-surface-1,var(--color-card))] p-5',
        'shadow-[var(--shadow-glow-card,var(--shadow-card))]',
        'transition-all duration-200 ease-out',
        'hover:shadow-[var(--shadow-card-hover)] hover:-translate-y-0.5',
        'animate-fade-in-up',
      )}
      style={{
        animationDelay: `${index * 70}ms`,
        animationFillMode: 'both',
        ['--kpi-accent' as string]: accentColor,
      }}
    >
      {/* Accent top stripe */}
      <div
        className="absolute inset-x-0 top-0 h-px"
        style={{ background: `linear-gradient(90deg, transparent, var(--kpi-accent), transparent)` }}
        aria-hidden="true"
      />
      {/* Label + icon row */}
      <div className="mb-4 flex items-center justify-between">
        <span className="text-[10px] font-semibold uppercase tracking-[0.1em] text-muted-foreground/50">
          {label}
        </span>
        <div className="flex h-7 w-7 items-center justify-center rounded-md bg-primary/8 ring-1 ring-primary/15">
          <Icon className="h-3.5 w-3.5 text-primary" aria-hidden="true" />
        </div>
      </div>
      <div className="text-[1.75rem] font-bold tabular-nums leading-none tracking-tight">{value}</div>
      <p className={cn('mt-2 text-xs font-medium', getTrendColor(trend, invertTrend))}>{subtext}</p>
    </div>
  )
}

import type { Metadata } from 'next'
import { CalendarDays, Users, DollarSign } from 'lucide-react'

export const metadata: Metadata = {
  title: {
    default: 'Sign in',
