export default function AuthLayout({ children }: AuthLayoutProps) {
  return (
    <div className="flex min-h-svh bg-[var(--color-auth-bg,oklch(6.5%_0.02_272))]">
      {/* Left panel — desktop only */}
      <div
        className="relative hidden lg:flex lg:w-5/12 xl:w-[44%] flex-col justify-between overflow-hidden p-10"
        style={{ background: 'oklch(6.5% 0.02 272)' }}
      >
        {/* Mesh glows */}
        <div
          className="pointer-events-none absolute inset-0"
          aria-hidden="true"
          style={{
            background:
              'radial-gradient(ellipse 70% 60% at 80% 10%, oklch(62% 0.24 292 / 0.18), transparent), radial-gradient(ellipse 50% 50% at 20% 90%, oklch(60% 0.22 230 / 0.10), transparent)',
          }}
        />

        {/* Logo */}
        <div className="relative z-10 flex items-center gap-2.5">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary shadow-[0_0_16px_oklch(62%_0.24_292_/_0.5)]">
            <span className="text-xs font-bold text-primary-foreground">IO</span>
