          <h2 className="text-2xl font-bold leading-snug tracking-tight text-white">
            The operating system for modern tattoo studios.
          </h2>
          <ul className="space-y-4">
            {FEATURE_BULLETS.map(({ icon: Icon, text }) => (
              <li key={text} className="flex items-center gap-3 text-sm text-white/70">
